<section class="auth-wrap"><div class="auth-aside"><span class="eyebrow">MAKE YOUR NEXT MOVE</span><h1>Build a path<br>that feels like<br><em>your own.</em></h1><p>Create an account to get started. Administrator accounts are created by the project administrator.</p></div><form class="form-card" method="post" action="<?= e(url('register')) ?>"><h2>Create your account</h2><p class="muted">A few details to get you started.</p><?= csrf_field() ?><input type="hidden" name="action" value="register"><label>Full name<input required name="name" maxlength="120" autocomplete="name"></label><label>Email address<input required type="email" name="email" maxlength="190" autocomplete="email"></label><label>I am a<select name="role" id="account-role"><option value="student">Student</option><option value="employer">Employer</option></select></label><label id="organization-field" hidden>Company or organization<input name="organization" maxlength="160"></label><label>Password <span class="hint">(at least 10 characters)</span><input required type="password" name="password" minlength="10" autocomplete="new-password"></label><button class="button full-width" type="submit">Create account</button><p class="form-foot">Already registered? <a href="<?= e(url('login')) ?>">Sign in</a></p></form></section>
